const event = $json.event || 'appointment_update';
const recipient = $json.patient_email || $json.doctor_email;
const patient = $json.patient_name || 'Doctor';
const doctor = $json.doctor_name || 'Nowshera Family Clinic';
const date = $json.appointment_date || '';
const time = $json.appointment_time || '';
const messages = { appointment_confirmed: 'Your appointment has been confirmed.', appointment_rejected: 'Your appointment request was rejected. Please choose another available time.', appointment_cancelled: 'Your appointment has been cancelled.', doctor_leave: 'Your appointment has been cancelled because the doctor is on leave.', appointment_reminder: 'Reminder: your appointment is tomorrow.', pending_expired: 'Your pending appointment expired and was cancelled.', doctor_invitation: 'You have been invited to join Nowshera Family Clinic.' };
const message = messages[event] || 'Your appointment has been updated.';
const setup = $json.setup_link ? `

Set your password here: ${$json.setup_link}` : '';
return [{ json: { recipient, email_subject: `Nowshera Family Clinic: ${event.replaceAll('_', ' ')}`, email_body: `Hello ${patient},

${message}

Doctor: ${doctor}
Date: ${date}
Time: ${time}${setup}

Thank you,
Nowshera Family Clinic` } }];
